import json
def solve(g):
    h,w=len(g),len(g[0]); o=[[0]*(w//3) for _ in range(h//3)]
    for r in range(h//3):
        for c in range(w//3):
            cnt={}
            for i in range(3*r,3*r+3):
                for j in range(3*c,3*c+3):
                    cnt[g[i][j]]=cnt.get(g[i][j],0)+1
            rare={k:v for k,v in cnt.items() if k!=0 and k!=5}
            if rare:
                m=max(rare.values()); best=[k for k in rare if rare[k]==m]
                best.sort()
                o[r][c]=best[0]
    return o
